<?php require 'config.php'; if(isLoggedIn()){header('Location: '.(isAdmin()?'admin/index.php':'index.php'));exit;} $error='';$return=trim($_GET['return']??$_POST['return']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pw=$_POST['password']??'';if($email===''||$pw==='')$error='Invalid email or password.';else{$st=$conn->prepare('SELECT id,name,email,password,role FROM users WHERE email=? LIMIT 1');$st->bind_param('s',$email);$st->execute();$u=$st->get_result()->fetch_assoc();if($u&&password_verify($pw,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['user_email']=$u['email'];$_SESSION['role']=$u['role'];$dest=$return!==''?$return:($u['role']==='admin'?'admin/index.php':'profile.php');if(strpos($dest,'http')===0||strpos($dest,'//')===0)$dest='profile.php';header('Location: '.$dest);exit;}else $error='Invalid email or password.';$st->close();}}
$pageTitle='Sign In | Ceylon Noir';require 'header.php';?><section class="auth-page"><div class="auth-card"><span class="gold-kicker">WELCOME BACK</span><h1>Sign in</h1><p class="muted">Access your Ceylon Noir account securely.</p><?php if(isset($_GET['error'])&&$_GET['error']==='admin'):?><div class="alert">Administrator access is required for that area.</div><?php endif;?><?php if($error):?><div class="alert"><?php echo e($error);?></div><?php endif;?><form method="post"><input type="hidden" name="return" value="<?php echo e($return);?>"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button class="gold-btn full" type="submit">SIGN IN</button></form><p class="auth-foot">New here? <a class="gold-link" href="register.php">Create an account</a></p></div></section><?php require 'footer.php';?>
